"""Usage: scratch_ds_osf.py <osf_id> ...  -> title, public, licence (name + year/holders), children, top-level file names/sizes (metadata only)."""
import sys, json, urllib.request
def get(url):
    req = urllib.request.Request(url, headers={"User-Agent":"scoping"})
    return json.load(urllib.request.urlopen(req, timeout=30))
def files(url, depth=0, maxdepth=2):
    try: d = get(url)
    except Exception as e: print("   files err", e); return
    for f in d["data"]:
        a = f["attributes"]
        print("   " + "  "*depth + f"{a['kind']}: {a['name']} size={a.get('size')}")
        if a["kind"] == "folder" and depth < maxdepth:
            files(f["relationships"]["files"]["links"]["related"]["href"], depth+1, maxdepth)
for nid in sys.argv[1:]:
    print("=====", nid)
    try:
        n = get(f"https://api.osf.io/v2/nodes/{nid}/?embed=license")
    except Exception as e:
        print("node err", e); continue
    a = n["data"]["attributes"]
    print("title:", a["title"], "| public:", a["public"], "| created:", a["date_created"][:10], "| category:", a["category"])
    lic = n["data"].get("embeds",{}).get("license",{})
    if "data" in lic: print("LICENCE:", lic["data"]["attributes"]["name"], "| node_license field:", a.get("node_license"))
    else: print("LICENCE: none set", lic.get("errors"), "| node_license field:", a.get("node_license"))
    print("description:", (a.get("description") or "")[:300].replace("\n"," "))
    try:
        ch = get(f"https://api.osf.io/v2/nodes/{nid}/children/")
        for c in ch["data"]: print("  child:", c["id"], c["attributes"]["title"])
    except Exception as e: print("children err", e)
    files(f"https://api.osf.io/v2/nodes/{nid}/files/osfstorage/")
EOF
